<?php
namespace KaarBooking\Component\KaarBooking\Administrator\View\Inspections;defined('_JEXEC') or die;use Joomla\CMS\Factory;use Joomla\CMS\MVC\View\HtmlView as BaseHtmlView;
final class HtmlView extends BaseHtmlView
