'search'].'%').')');if($this->filters['driver'])$q->where('i.driver_id='.(int)$this->filters['driver']);if($this->filters['company'])$q->where('v.company_id='.(int)$this->filters['company']);if($this->filters['type'])$q->where('v.vehicle_type_id='.(int)$this->filters['type']);if($this->filters['result']!=='')$q->where('i.result='.$db->quote($this->filters['result']));$q->order('i.inspection_date DESC');$this->items=$db->setQuery($q,0,500)->loadAssocList()?:[];parent::display($tpl);
